<script lang="ts" module>
	import type { Snippet } from 'svelte';import type { RxColor } from '$lib/registry/lib/color';
	export interface LinkBarItem { id:string;label:string;href?:string;icon?:Snippet;disabled?:boolean }
	export interface LinkBarProps { items:LinkBarItem[];active?:string;color?:RxColor;variant?:'default'|'glow'|'magnet'|'pill'|'slide'|'underline';size?:'sm'|'md'|'lg';tone?:'default'|'danger'|'success'|'warn';separated?:boolean;strength?:number;ariaLabel?:string;onActiveChange?:(id:string)=>void }
</script>
<script lang="ts">
	import {styleColor}from'$lib/registry/lib/color';
	let {items,active=$bindable(''),color,variant='default',size='md',tone='default',separated=false,strength=8,ariaLabel='Section navigation',onActiveChange}:LinkBarProps=$props();
	let root:HTMLElement,frame=0,hovered:HTMLElement|null=null,pointerX=0,pointerY=0,ready=$state(false);let indicator=$state('opacity:0');
	function geometry(el:HTMLElement){const pad=variant==='magnet'?10:0,y=variant==='pill'||variant==='magnet'?el.offsetTop:el.offsetTop+el.offsetHeight-(variant==='slide'||variant==='underline'||variant==='default'?2:el.offsetHeight);const h=variant==='pill'?el.offsetHeight:variant==='magnet'?el.offsetHeight+2:variant==='glow'?0:2;return`opacity:1;transform:translate(${el.offsetLeft-pad}px,${y-(variant==='magnet'?1:0)}px);width:${el.offsetWidth+pad*2}px;height:${h}px`}
