	function magnet(){frame=0;if(variant!=='magnet')return;if(!hovered){update();return}indicator=geometry(hovered);const r=hovered.getBoundingClientRect(),x=(pointerX-(r.left+r.width/2))/(r.width/2),y=(pointerY-(r.top+r.height/2))/(r.height/2);hovered.style.transform=`translate(${(x*strength).toFixed(2)}px,${(y*strength).toFixed(2)}px)`}
